#!/usr/bin/env bash
parse() {
    local OPTIND opt verbose=0 output=-
    while getopts ':vo:' opt; do
        case $opt in
            v) verbose=1 ;;
            o) output=$OPTARG ;;
            :) echo "option -$OPTARG needs an argument" >&2; return 2 ;;
            \?) echo "unknown option -$OPTARG" >&2; return 2 ;;
        esac
    done
    shift $((OPTIND - 1))
    echo "verbose=$verbose output=$output operands=$*"
}
