#!/usr/bin/env bash
cli() {
    local name=anonymous args=() arg
    for arg in "$@"; do
        case $arg in
            --name=*) name=${arg#--name=} ;;
            *) args+=("$arg") ;;
        esac
    done
    set -- "${args[@]}"
    local OPTIND opt n=1 quiet=0
    while getopts ':qn:' opt; do
        case $opt in
            q) quiet=1 ;;
            n) n=$OPTARG ;;
            *) echo 'usage: cli [-q] [-n NUM] [--name=VALUE] FILE...' >&2; return 2 ;;
        esac
    done
    shift $((OPTIND - 1))
    echo "n=$n quiet=$quiet name=$name rest=$*"
}
